package com.luci.pianoroom;
import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public final class SfzCompatibilityTest {
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 static ByteBuffer compile(File root,String source,String filename)throws Exception {File sfz=new File(root,"instrument.sfz"),out=new File(root,filename);Files.write(sfz.toPath(),source.getBytes("UTF-8"));SfzBank.compile(sfz,root,out,"Compatibility");return ByteBuffer.wrap(Files.readAllBytes(out.toPath())).order(ByteOrder.LITTLE_ENDIAN);}
 static void fails(File root,String source,String reason)throws Exception {try{compile(root,source,"bad.prb");throw new AssertionError("Accepted "+reason);}catch(IOException e){check(e.getMessage().contains(reason),"Expected "+reason+", got "+e);}}
 static byte[] wav(File root,String name,int bits,int channels,boolean loop)throws Exception {int frames=8192,width=bits/8,extra=loop?68:0;ByteBuffer data=ByteBuffer.allocate(44+frames*width*channels+extra).order(ByteOrder.LITTLE_ENDIAN);data.put(new byte[]{82,73,70,70}).putInt(data.capacity()-8).put(new byte[]{87,65,86,69,102,109,116,32}).putInt(16).putShort((short)1).putShort((short)channels).putInt(48000).putInt(48000*width*channels).putShort((short)(width*channels)).putShort((short)bits).put(new byte[]{100,97,116,97}).putInt(frames*width*channels);for(int n=0;n<frames;n++)for(int ch=0;ch<channels;ch++){int v=n%4==0?-1:n%4==1?1:n%4==2?(bits==24?-8388607:-32767):(bits==24?8388607:32767);for(int b=0;b<width;b++)data.put((byte)(v>>(8*b)));}if(loop){data.put(new byte[]{115,109,112,108}).putInt(60);for(int n=0;n<7;n++)data.putInt(0);data.putInt(1).putInt(0).putInt(0).putInt(0).putInt(12).putInt(8000).putInt(0).putInt(0);}Files.write(new File(root,name).toPath(),data.array());return data.array();}
 static void flac(File root,int bits,int channels)throws Exception {String name="precision-"+bits+"-"+channels;wav(root,name+".wav",bits,channels,false);Process p=new ProcessBuilder("ffmpeg","-nostdin","-v","error","-y","-i",new File(root,name+".wav").getPath(),"-c:a","flac",new File(root,name+".flac").getPath()).inheritIO().start();check(p.waitFor()==0,"Independent FLAC encoding");byte[] wav=compile(root,"<region> key=60 sample="+name+".wav","wav.prb").array(),flac=compile(root,"<region> key=60 sample="+name+".flac","flac.prb").array();check(Arrays.equals(wav,flac),"WAV and FLAC produce exactly identical float32 for "+bits+"-bit "+channels+" channels");byte[] damaged=Files.readAllBytes(new File(root,name+".flac").toPath());damaged[damaged.length-15]^=19;Files.write(new File(root,"corrupt.flac").toPath(),damaged);try{compile(root,"<region> sample=corrupt.flac","bad.prb");throw new AssertionError("Corrupt FLAC accepted");}catch(IOException expected){}Files.write(new File(root,"short.flac").toPath(),Arrays.copyOf(damaged,damaged.length/2));try{compile(root,"<region> sample=short.flac","bad.prb");throw new AssertionError("Truncated FLAC accepted");}catch(IOException expected){}
 }
 public static void main(String[] args)throws Exception {File root=new File(args[0]);root.mkdirs();wav(root,"a=b.wav",24,1,false);wav(root,"loop.wav",24,1,true);Files.write(new File(root,"zones.inc").toPath(),("\uFEFF<master> key=$KEY amplitude=50 volume=-2 master_label=\"a=b <region> // preserved\"\n<group> hivel=70\n<region> sample=\"a=b.wav\"\n<master> key=62\n<region> sample=\"a=b.wav\"\n").getBytes("UTF-8"));ByteBuffer b=compile(root,"/* multiline\ncomment */\n#define $KEY C4\n<global> ampeg_release=0.4\n#include \"zones.inc\"\n","macro.prb");check(b.getInt(76)==60&&b.getInt(76+12)==70,"macro key and group velocity inherited");check(Math.abs(b.getFloat(76+72)-8.0206f)<.001f,"static amplitude converted to attenuation");check(b.getInt(76+96)==62&&b.getInt(76+96+12)==127,"second master resets previous group");check(b.getFloat(76+96+72)==0,"second master resets previous amplitude/volume");check(b.getFloat(76+96+92)==.4f,"global envelope inherited through master");b=compile(root,"<region> sample=loop.wav key=60","embedded.prb");check(b.getInt(76+28)==12&&b.getInt(76+32)==8000&&b.getInt(76+36)==1,"WAV loop metadata/default mode respected");b=compile(root,"<region> sample=loop.wav loop_mode=no_loop","no-loop.prb");check(b.getInt(76+36)==0,"explicit no_loop overrides embedded metadata");b=compile(root,"<region> sample=loop.wav loop_mode=loop_sustain loop_start=100 loop_end=400 end=500","explicit.prb");check(b.getInt(76+28)==100&&b.getInt(76+32)==400&&b.getInt(76+36)==2,"explicit loop overrides metadata");b=compile(root,"<region> sample=\"a=b.wav\" amplitude=0 volume=12","silent.prb");check(b.getFloat(76+72)==1000,"zero amplitude preserved as underflow to zero in float engine");fails(root,"<region> sample=loop.wav loop_end=6000 end=5000","loop_end");fails(root,"#define $A $B\n#define $B $A\n<region> sample=$A","recursiva");fails(root,"<region> key=$UNDEFINED sample=loop.wav","não definida");fails(root,"<region> sample=loop.wav cutoff=1000","cutoff");fails(root,"<region> sample=missing.wav","ausente");fails(root,"<region> sample=loop.wav trigger=release","soltura");Files.write(new File(root,"recursive.inc").toPath(),"#include recursive.inc".getBytes("UTF-8"));fails(root,"#include recursive.inc","recursivo");fails(root,"#include ../escape.inc","fora do banco");check(BankImportHelp.directReason("PIANO.NKI").contains("Kontakt"),"Kontakt format explanation");check(BankImportHelp.directReason("piano.sfz").contains("ZIP"),"standalone SFZ packaging help");if(args.length>1&&args[1].equals("flac"))for(int bits:new int[]{16,24})for(int channels:new int[]{1,2})flac(root,bits,channels);System.out.println("SFZ compatibility: macros/BOM/includes/master/reset/quoted labels/amplitude/embedded loops/overrides/limits/errors passed"+(args.length>1?"; independent lossless FLAC16/24 mono/stereo, corruption and truncation passed":""));}
}
